import{_ as t,o as a,c as r,a4 as s}from"./chunks/framework.BabNWGMA.js";const i=JSON.parse('{"title":"🏭 炼油化工设备 知识点笔记","description":"","frontmatter":{},"headers":[],"relativePath":"subjects/炼油化工设备.md","filePath":"subjects/炼油化工设备.md","lastUpdated":1787466820000}'),e={name:"subjects/炼油化工设备.md"};function l(n,o,p,u,c,g){return a(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="🏭-炼油化工设备-知识点笔记" tabindex="-1">🏭 炼油化工设备 知识点笔记 <a class="header-anchor" href="#🏭-炼油化工设备-知识点笔记" aria-label="Permalink to &quot;🏭 炼油化工设备 知识点笔记&quot;">​</a></h1><blockquote><p>共 <strong>11</strong> 个知识点 · 隔天自动更新</p></blockquote><h2 id="离心泵的工作原理" tabindex="-1">离心泵的工作原理 <a class="header-anchor" href="#离心泵的工作原理" aria-label="Permalink to &quot;离心泵的工作原理&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 30% | <strong>创建:</strong> 2026-08-08 | <strong>最近复习:</strong> 2026-08-10</p></blockquote><blockquote><p>掌握度进度: ███░░░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>叶轮高速旋转产生离心力,液体被甩向泵壳获得动能和压能。区别于往复泵(活塞挤压)、齿轮泵(啮合输送)、气动泵(压缩空气)</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>催化裂化装置常用离心泵输送油品</p></details><hr><h2 id="主风机振动超标的常见原因" tabindex="-1">主风机振动超标的常见原因 <a class="header-anchor" href="#主风机振动超标的常见原因" aria-label="Permalink to &quot;主风机振动超标的常见原因&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 100% | <strong>创建:</strong> 2026-08-08 | <strong>最近复习:</strong> 2026-08-15</p></blockquote><blockquote><p>掌握度进度: ██████████</p></blockquote><p><strong>核心内容:</strong></p><p>①转子不平衡(积垢结焦/叶片脱落/异物损伤)②喘振(工况进入不稳定区)③轴承磨损或润滑不良④对中不良/地脚螺栓松动⑤仪表故障(探头/变送器误报)</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>催化裂化装置主风机,振动超标先查仪表再查机械</p></details><hr><h2 id="三泵输送原理对比" tabindex="-1">三泵输送原理对比 <a class="header-anchor" href="#三泵输送原理对比" aria-label="Permalink to &quot;三泵输送原理对比&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 70% | <strong>创建:</strong> 2026-08-13 | <strong>最近复习:</strong> 2026-08-13</p></blockquote><blockquote><p>掌握度进度: ███████░░░</p></blockquote><p><strong>核心内容:</strong></p><p>离心泵=叶片式(叶轮离心力甩出,流量大连续);往复泵=容积式(活塞挤压,高压小流量);齿轮泵=容积式(啮合输送,适合小流量高压粘度大;不适合含固体颗粒/易结焦介质)</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>离心泵:油浆泵;往复泵:注水泵;齿轮泵:润滑油泵</p></details><hr><h2 id="离心泵气蚀-汽蚀-现象" tabindex="-1">离心泵气蚀(汽蚀)现象 <a class="header-anchor" href="#离心泵气蚀-汽蚀-现象" aria-label="Permalink to &quot;离心泵气蚀(汽蚀)现象&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 60% | <strong>创建:</strong> 2026-08-13 | <strong>最近复习:</strong> 2026-08-13</p></blockquote><blockquote><p>掌握度进度: ██████░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>入口局部压力&lt;液体饱和蒸汽压→液体汽化→气泡到高压区破裂冲击叶轮→蜂窝状麻点+噼啪声+流量扬程下降。措施:提高入口压力/降低入口温度/降低安装高度/清理入口过滤器/切换机泵</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>催化裂化高温油浆泵常见;拆检叶轮入口蜂窝状麻点即气蚀</p></details><hr><h2 id="离心泵气缚现象" tabindex="-1">离心泵气缚现象 <a class="header-anchor" href="#离心泵气缚现象" aria-label="Permalink to &quot;离心泵气缚现象&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 70% | <strong>创建:</strong> 2026-08-15 | <strong>最近复习:</strong> 2026-08-15</p></blockquote><blockquote><p>掌握度进度: ███████░░░</p></blockquote><p><strong>核心内容:</strong></p><p>气缚:泵壳内充满气体,叶轮旋转但吸不上液体,空转不上量(启动前未灌泵排气导致)。气蚀:液体汽化气泡破裂损坏叶轮(运行中)。区别:气缚=气体没排掉;气蚀=液体汽化</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>启动前必须灌泵排气防气缚;气缚时电流小、不上量</p></details><hr><h2 id="离心泵启动前准备工作" tabindex="-1">离心泵启动前准备工作 <a class="header-anchor" href="#离心泵启动前准备工作" aria-label="Permalink to &quot;离心泵启动前准备工作&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 70% | <strong>创建:</strong> 2026-08-15 | <strong>最近复习:</strong> 2026-08-15</p></blockquote><blockquote><p>掌握度进度: ███████░░░</p></blockquote><p><strong>核心内容:</strong></p><p>①灌泵排气(防气缚,最关键)②盘车检查转动灵活③检查密封/冲洗系统④进口阀全开、出口阀关闭⑤检查轴承润滑/冷却水。关阀启动:出口阀关闭时功率最小,减小启动电流防电机过载</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>启动顺序:灌泵排气→盘车→开进口阀→关阀启动→正常后缓开出口阀</p></details><hr><h2 id="离心泵的结构与主要零部件" tabindex="-1">离心泵的结构与主要零部件 <a class="header-anchor" href="#离心泵的结构与主要零部件" aria-label="Permalink to &quot;离心泵的结构与主要零部件&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-27 | <strong>最近复习:</strong> 2026-08-27</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>离心泵由叶轮、泵壳(蜗壳)、轴、密封(机械密封/填料密封)、轴承、平衡装置等组成。叶轮是唯一做功部件:将电机机械能转化为流体动能与压能;泵壳收集液体并将部分动能转为压能(蜗壳断面渐扩,流速降低、压力升高);轴封防止高压液体外漏和空气漏入;平衡装置(平衡孔/平衡盘)抵消轴向推力;轴承承受径向与轴向载荷。选型要点:输送介质、流量Q、扬程H、汽蚀余量、材质耐蚀耐磨。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例:某常减压装置热油泵输送380°C渣油,叶轮材质应选耐高温抗热疲劳的合金钢(如Cr5Mo),轴封不能用普通橡胶填料(高温老化),需用金属波纹管机械密封或高温填料。判断:该泵属于离心泵,选型时首先要确定Q和H。</p></details><hr><h2 id="离心泵的汽蚀现象与防治" tabindex="-1">离心泵的汽蚀现象与防治 <a class="header-anchor" href="#离心泵的汽蚀现象与防治" aria-label="Permalink to &quot;离心泵的汽蚀现象与防治&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-27 | <strong>最近复习:</strong> 2026-08-27</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>汽蚀(空化)机理:泵入口处绝对压力降至该温度下液体饱和蒸气压时,液体汽化形成气泡;气泡随液流进入高压区(叶轮出口)瞬间凝结溃灭,产生巨大冲击力(局部压力可达数百大气压),反复冲击叶轮叶片与泵壳,造成金属剥蚀(蜂窝状麻点)、振动与噪声,同时流量、扬程、效率下降。判据:泵入口有效汽蚀余量NPSHa小于必需汽蚀余量NPSHr即发生汽蚀。防治:①提高入口压力(灌注头/倒灌安装、增压泵);②降低介质温度;③减小吸入管路阻力(短而直、少弯头阀门、增大管径);④控制流量不要过大;⑤选泵时NPSHa&gt;NPSHr+0.5m;⑥材质抗汽蚀(不锈钢、表面硬化)。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例:某催化裂化装置油浆泵运行中振动大、出口压力波动、叶轮出现蜂窝状麻点。判断为汽蚀。检查发现入口过滤器堵塞、吸入管线过长弯头多。处理:清理过滤器、改造吸入管线(加大管径、减少弯头),泵恢复正常。原理:过滤器堵塞+管线阻力大→入口压力下降→NPSHa&lt;NPSHr→汽蚀。</p></details><hr><h2 id="离心泵气缚现象与灌泵操作" tabindex="-1">离心泵气缚现象与灌泵操作 <a class="header-anchor" href="#离心泵气缚现象与灌泵操作" aria-label="Permalink to &quot;离心泵气缚现象与灌泵操作&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-27 | <strong>最近复习:</strong> 2026-08-27</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>气缚:泵壳内积存气体(空气)时,气体密度远小于液体,叶轮旋转只能产生很小的离心力,不足以把液体吸上来,泵虽运转但不出液。气缚与汽蚀本质区别:气缚是泵内进空气(外部气体),发生在启动时;汽蚀是液体自身汽化(内部气泡),发生在运行中。防治:启动前必须灌泵排气(打开泵壳顶部排气阀,直到流出连续液体再关闭),保证泵壳和吸入管路充满液体。泵长期停用或检修后更要先灌泵。若灌泵后仍不上量,检查吸入管漏气、底阀(止回阀)失效、入口过滤器堵塞。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例:某装置离心泵检修后启动,电机运转正常但出口无流量,压力表读数低。操作工判断:泵内进了空气(气缚)。处理:打开顶部排气阀重新灌泵,排出气体后出口压力恢复、流量正常。问:气缚与汽蚀的区别?答:气缚=外部空气进泵,启动时发生;汽蚀=液体自身汽化,运行中发生。</p></details><hr><h2 id="列管式换热器强化传热-折流挡板与多壳程" tabindex="-1">列管式换热器强化传热:折流挡板与多壳程 <a class="header-anchor" href="#列管式换热器强化传热-折流挡板与多壳程" aria-label="Permalink to &quot;列管式换热器强化传热:折流挡板与多壳程&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-08-29 | <strong>最近复习:</strong> 2026-08-29</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>列管式换热器一般不采用多壳程结构(壳程加纵向隔板分程,制造检修复杂、成本高),而采用折流挡板(折流板)以强化壳程传热。折流挡板迫使壳程流体横向反复冲刷管束,提高湍流度,增大壳程对流传热系数,从而强化传热。常见形式:弓形(单/双/三弓形)、圆环形、螺旋形等。干扰项辨析:隔板=多壳程/管程分程用;波纹板、翅片板属于板式/板翅式换热器元件,不是列管式壳程强化手段。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例题:列管式换热器一般不采用多壳程结构,而采用( )以强化传热效果。A.隔板 B.波纹板 C.翅片板 D.折流挡板 → 答案 D。折流挡板迫使壳程流体横向冲刷管束,提高湍流度强化传热;多壳程因制造检修复杂一般不采用。</p></details><hr><h2 id="列管式换热器强化壳程传热-折流挡板-问答题" tabindex="-1">列管式换热器强化壳程传热:折流挡板(问答题) <a class="header-anchor" href="#列管式换热器强化壳程传热-折流挡板-问答题" aria-label="Permalink to &quot;列管式换热器强化壳程传热:折流挡板(问答题)&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 10% | <strong>创建:</strong> 2026-09-03 | <strong>最近复习:</strong> 2026-09-03</p></blockquote><blockquote><p>掌握度进度: █░░░░░░░░░</p></blockquote><hr>',76)])])}const h=t(e,[["render",l]]);export{i as __pageData,h as default};
